/* ===== 응원단 v22 revision2: 40명 단원 + 8명 팀장, 512px 원본 =====
   단원 ph22는 manifest index(0..47), 기존 ph/ph15와 별개입니다.
   512 시트를 앱에 포함하므로 내려받은 HTML에서도 동작합니다. 웹 빌드는 기존
   splitWebsite가 data URI를 해시 이미지로 추출하므로 별도 배포 도구 변경이 없습니다. */
const shash=s=>[...String(s)].reduce((a,c)=>(a*31+c.charCodeAt(0))|0,7)>>>0;
const CHEER22_PALETTE=[['red','#D3263A'],['navy','#172A50'],['blue','#2161C6'],['black','#181C24'],['orange','#F3792A'],['green','#16835A'],['purple','#7546AD'],['sky','#62BCE6']];
const CHEER22_CACHE=new Map();
/* 구단 대표색(사용자 지정 배지 색 포함)과 RGB 거리가 가까운 계열부터 씁니다. */
function cheer22Pool(tid,cap){ const t=(G.teams||[]).find(t=>String(t.id)===String(tid)), hex=tpal(t)[0], rgb=h=>{ h=String(h).replace('#',''); if(h.length===3)h=[...h].map(c=>c+c).join(''); const n=parseInt(h,16); return [n>>>16&255,n>>>8&255,n&255]; }, own=rgb(hex);
  return CHEER22_PALETTE.map((x,i)=>({i,d:rgb(x[1]).reduce((d,v,k)=>d+(v-own[k])**2,0)})).sort((a,b)=>a.d-b.d||a.i-b.i).flatMap(x=>cap?[x.i*6+5]:[0,1,2,3,4].map(k=>x.i*6+k)); }
function cheer22Tid(S){ if(G.fanOps&&G.fanOps.cs===S)return G.user; for(const [tid,F] of Object.entries(G.fanYrT||{}))if(F&&F.cs===S)return +tid; for(const t of G.teams||[])if(t.fanOps&&t.fanOps.cs===S)return t.id; return G.user; }
/* 사진만 저장합니다. save()의 튜토리얼·안내 진행은 보기만 한 화면에서 호출하지 않습니다.
   기존 저장 타이머를 써서 탭 닫기/슬롯 전환 때도 사진 배정을 같이 확정합니다. */
function cheer22Persist(){ if(!G)return; if(_svT)clearTimeout(_svT); _svT=setTimeout(()=>{ _svT=null; saveStoreAsync(); },700); }
function cheer22Assign(S,tid){ if(!S||!Array.isArray(S.L))return 0; const pool=cheer22Pool(tid,false), valid=new Set(pool), used=new Set(), pending=[]; let changed=0;
  const L=[...S.L].sort((a,b)=>String(a.id).localeCompare(String(b.id),'en',{numeric:true})||String(a.name).localeCompare(String(b.name),'ko'));
  for(const m of L){ if(Object.prototype.hasOwnProperty.call(m,'ph15')){delete m.ph15;changed++;} if(Object.prototype.hasOwnProperty.call(m,'ph')){delete m.ph;changed++;}
    if(Number.isInteger(m.ph22)&&valid.has(m.ph22)&&!used.has(m.ph22))used.add(m.ph22); else pending.push(m); }
  for(const m of pending){ const free=pool.filter(i=>!used.has(i)), first=free[0], group=free.length?free.filter(i=>Math.floor(i/6)===Math.floor(first/6)):pool;
    m.ph22=group[shash('cheer22:'+tid+':'+m.id+':'+m.name)%group.length]; used.add(m.ph22); changed++; }
  return changed; }
function cheer22Cap(c,tid){ if(!c)return 0; if(Number.isInteger(c.ph22)&&c.ph22>=0&&c.ph22<48&&c.ph22%6===5)return 0; c.ph22=cheer22Pool(tid,true)[0]; return 1; }
/* 불러오기 공통 수리(fanOpsFix)는 migrateDraft에서 가져오기·슬롯 복원 때도 호출됩니다.
   현재/떠난 구단/AI에 보존된 응원단만 정리하며, 대행사 계약이나 단원을 만들지 않습니다. */
function cheer22Migrate(){ if(!G||!Array.isArray(G.teams))return 0; const seen=new Set(), states=[]; if(G.fanOps)states.push([G.user,G.fanOps]); for(const [tid,F] of Object.entries(G.fanYrT||{}))if(F)states.push([+tid,F]); for(const t of G.teams)if(t.fanOps)states.push([t.id,t.fanOps]); let n=0;
  for(const [tid,F] of states){ if(seen.has(F))continue; seen.add(F); n+=cheer22Assign(F.cs,tid); if(F.crew&&F.crew.cap)n+=cheer22Cap(F.crew.cap,tid); } return n; }
const cheer22LegacyFanFix=fanOpsFix;
fanOpsFix=(...args)=>{ const n=cheer22LegacyFanFix(...args), photos=cheer22Migrate(); if(photos)cheer22Persist(); return n+photos; };
function cheer22Src(i){ if(!Number.isInteger(i)||i<0||i>=48)return null; if(CHEER22_CACHE.has(i))return CHEER22_CACHE.get(i); const im=faceImg('cheer22_revision2',CHEER22_SHEET); if(!im||!im.ok)return im&&!im.bad?F6WAIT:null;
  const cv=document.createElement('canvas'); cv.width=cv.height=512; const ctx=cv.getContext('2d'); if(!ctx)return null; ctx.drawImage(im,(i%8)*512,Math.floor(i/8)*512,512,512,0,0,512,512); const u=cv.toDataURL('image/png'); CHEER22_CACHE.set(i,u); return u; }
/* 기존 인물 상세·팀장 카드도 face8Src를 쓰므로 v22 키만 여기서 처리합니다. */
const cheer22LegacyFaceSrc=face8Src;
face8Src=c=>typeof c==='string'&&/^cheer22:\d+$/.test(c)?cheer22Src(Number(c.slice(8))):cheer22LegacyFaceSrc(c);
const F8R=(r,f)=>{ if(typeof FACE8==='undefined')return []; return FACE8.ids.map((x,i)=>x.r===r&&(f==null||x.f===f)?i:-1).filter(i=>i>=0); };
/* 남성 응원단장은 기존 v12 사진, 여성 치어리더 팀장은 가까운 색 계열 ccap22입니다. */
function crewPh(c){ if(c.job==='cap'){ if(cheer22Cap(c,G.user))cheer22Persist(); return 'cheer22:'+c.ph22; } const P=F8R('clead',0), o=(G.crewPhO&&G.crewPhO[c.id])||0; return P.length?P[(shash('cr'+c.id+c.name)+o)%P.length]:null; }
function cheerPh(S,m){ if(cheer22Assign(S,cheer22Tid(S)))cheer22Persist(); return Number.isInteger(m.ph22)?'cheer22:'+m.ph22:null; }
function phImg(c,alt){ const u=c!=null&&typeof face8Src==='function'?face8Src(c):null; return u?`<img src="${u}" alt="${esc(alt||'')}">`:''; }
const fatCol=v=>v>=80?'var(--bad)':v>=60?'var(--warn)':'var(--good)';
function cheerCard(S,m,up){ const st=m.inj?`<span class="pill bad">부상 ${m.inj}일</span>`:m.sl?`<span class="pill warn">슬럼프 ${m.sl}일</span>`:up?'<span class="pill good">다음 무대</span>':'<span class="pill">대기</span>';
  const fol=m.fol>=10000?(m.fol/10000).toFixed(m.fol>=100000?0:1)+'만':m.fol.toLocaleString('ko-KR');
  return `<div class="chm${up?' up':''}${m.inj?' inj':''}"><div class="crew-h"><span class="crew-av">${(G.cimg&&G.cimg[cheerKey(m)])?`<img src="${G.cimg[cheerKey(m)]}" alt="">`:phImg(cheerPh(S,m),m.name)}${cimgBtns(cheerKey(m))}</span><div><button class="lnk" data-a="person" data-v="chm:${m.id}"><b>${esc(m.name)}</b></button><span class="cimg-b"><button class="btn small" data-a="cheerPhNext" data-v="${m.id}" title="다른 템플릿 사진으로">다른 사진</button></span><span class="small muted">${m.age}세 · ${m.yrs?m.yrs+'년 차':'신인'} · 월 ${money(cheerFee(m,S.ag))}</span><span class="small">SNS 팔로워 ${fol}</span></div></div>
    <div class="crew-at chm-at">${CHEER_AT.map(([k,l])=>`<span><i>${l}</i><b style="color:${m[k]>=15?'var(--good)':m[k]<=7?'var(--bad)':'var(--ink)'}">${m[k]}</b></span>`).join('')}</div>
    <div class="chm-f"><span class="small">피로 <b style="color:${fatCol(m.fat)}">${m.fat}</b></span><i><u style="width:${m.fat}%;background:${fatCol(m.fat)}"></u></i>${st}</div>
    <div class="row" style="gap:4px"><button class="btn small${!S.auto&&m.on?' primary':''}" data-a="cheerOn" data-v="${m.id}"${m.inj?' disabled':''}>${S.auto?(up?'휴식 주기':'선발로'):m.on?'선발':'휴식'}</button><span class="small muted">출연 ${m.app}회</span></div></div>`; }
function cheerView(){ if(G.unemp)return ''; if(!(G.fanOps&&G.fanOps.cs))return `<p class="small muted">아직 응원단 대행사와 계약하지 않았습니다. 대행사를 고르면 단원 ${CHEER_N[(G.fanOps&&G.fanOps.cheer)||0]}명이 오고, 그때부터 월 수수료가 나가고 홈 관중 효과가 생깁니다. 신규 단원 배정 전 최대 월 수수료 기준으로 운영 자금을 확보해야 하며, 실제 배정된 단원 요금만 청구합니다.</p><div class="chips">${Object.entries(CHEER_AG).map(([k,a])=>`<button data-a="cheerAg" data-v="${k}">${esc(a.l)} · 수수료 ${Math.round(a.fee*100)}%</button>`).join('')}</div>${UI.cheerMsg?`<div class="note">${esc(UI.cheerMsg)}</div>`:''}`; /* 보기만 해서는 응원단을 만들지 않는다(검수 11-09j) */ const S=G.fanOps.cs, F=G.fanOps, lv=F.cheer||0, up=new Set(cheerStage(S).map(m=>m.id)), pw=cheerPower(S), att=cheerAtt();
  const ag=Object.entries(CHEER_AG).map(([k,a])=>`<button data-a="cheerAg" data-v="${k}" class="${S.ag===k?'on':''}">${esc(a.l)} · 수수료 ${Math.round(a.fee*100)}%</button>`).join('');
  const L=[...S.L].sort((a,b)=>up.has(b.id)-up.has(a.id)||b.pop-a.pop);
  const ml=cheerMeetLeft();
  return `${sceneImg(sceneOf(['cheer_basic','cheer_expanded','cheer_large'][lv],G.user+':'+G.year),'응원 무대')}
    <p class="small muted">응원단은 대행사와 계약합니다(실제 구단들도 외주). 대행사마다 수수료와 단원 실력이 다르고, 바꾸면 단원이 모두 바뀝니다(시즌 중에는 못 바꿈). 홈경기마다 ${CHEER_STAGE[lv]}명이 무대에 서고, 무대에 서면 피로가 쌓입니다. 지친 단원을 계속 세우면 부상·슬럼프가 옵니다(체력·성실성이 높으면 덜함). 무대 힘(댄스·팬서비스·인기)이 홈 관중을 조금 늘리고, 팬서비스는 팬 여론, 인기 단원은 상품 수입과 화제 기사를 만듭니다. 응원단 단계를 올리면 단원이 늘어납니다. 신규 단원 배정 전 최대 월 수수료 기준으로 운영 자금을 확보해야 하며, 실제 단원 요금만 청구합니다.</p>
    <div class="chips">${ag}</div><p class="small muted">${esc(CHEER_AG[S.ag].d)}</p>
    <div class="fo-sum small"><span>단원 <b>${S.L.length}명</b></span><span>무대 <b>${up.size}/${CHEER_STAGE[lv]}명</b></span><span>무대 힘 <b>${pw.toFixed(1)}</b></span><span>홈 관중 <b style="color:${att>=0?'var(--good)':'var(--bad)'}">${att>=0?'+':''}${(att*100).toFixed(1)}%</b></span><span>월 수수료 <b>${money(cheerPay())}</b></span></div>
    <div class="row" style="gap:6px;flex-wrap:wrap"><button class="btn small${S.auto?' primary':''}" data-a="cheerAuto">${S.auto?'자동 순환 중':'직접 정하는 중'}</button><button class="btn small" data-a="cheerMeet"${ml?' disabled':''}>${ml?esc(ml):'치어리더 팬 사인회 '+money(5)}</button></div>
    <p class="small muted">${S.auto?'자동 순환: 덜 지친 단원부터 무대에 섭니다. 단원 버튼을 누르면 직접 정하기로 바뀝니다.':'직접 정하기: 선발로 둔 단원 중 덜 지친 순서로 무대에 섭니다. 선발이 모자라면 무대 힘이 줄어듭니다.'}</p>
    ${UI.cheerMsg?`<div class="note">${esc(UI.cheerMsg)}</div>`:''}
    <div class="chm-g">${L.map(m=>cheerCard(S,m,up.has(m.id))).join('')}</div>`; }
Object.assign(A,{ cheerOn(v){ UI.cheerMsg=cheerOn(v); save(); render(); }, cheerAuto(){ UI.cheerMsg=cheerAuto(); save(); render(); }, cheerAg(v){ UI.cheerMsg=cheerAg(v); cheer22Migrate(); save(); render(); }, cheerMeet(){ UI.cheerMsg=cheerMeet(); save(); render(); } });

/* 응원단·치어리더 사진 바꾸기(커뮤니티 건의 11-11): 템플릿 사진을 다음 것으로 넘긴다. 갤러리 사진은 '사진' 버튼 */
Object.assign(A,{ cheerPhNext(v){ const S=G.fanOps&&G.fanOps.cs, m=S&&S.L.find(x=>String(x.id)===String(v)); if(!m)return; cheer22Assign(S,cheer22Tid(S)); const Q=cheer22Pool(cheer22Tid(S),false), used=new Set(S.L.filter(x=>x!==m).map(x=>x.ph22)); let i=Q.indexOf(m.ph22); for(let k=0;k<Q.length;k++){ i=(i+1)%Q.length; if(!used.has(Q[i]))break; } m.ph22=Q[i]; save(); render(); },
  crewPhNext(v){ const c=[...Object.values(G.fanOps&&G.fanOps.crew||{}),...(G.crewMkt&&G.crewMkt.L||[])].find(c=>String(c.id)===String(v)); if(c&&c.job==='cap'){ cheer22Cap(c,G.user); const Q=cheer22Pool(G.user,true); c.ph22=Q[(Q.indexOf(c.ph22)+1)%Q.length]; } else { G.crewPhO=G.crewPhO||{}; G.crewPhO[v]=(G.crewPhO[v]||0)+1; } save(); render(); } });

/* v22 manifest revision2 · 4096×3072 · 8열×6행 · 원본 SHA256 99a042140909f36819e840955396a5b4bfbf6a3d79b35d5dad6a16fed8031fd2
   자동 포함한 손실 WebP q80 원본입니다. 사진을 바꾸면 manifest와 이 바이트를 함께 갱신합니다. */
const CHEER22_SHEET='data:image/webp;base64,';
